// @FIGURE_CODE_BEGIN
var FIG_PINK = '#f4d7d4', FIG_GREEN = '#e3ecd5';

var CASES = [
  {
    key: 'ΔH>0, ΔS<0', dH: 40, dS: -0.055, color: '#c0392b',
    l1: 'ΔH > 0', l2: 'ΔS < 0', labelT: 300,
    title: 'ΔH > 0, ΔS < 0 — never spontaneous',
    desc: 'Both terms work against the reaction: the positive ΔH puts the line in the pink half at low T, and because ΔS is negative the term −TΔS is positive, so heating pushes ΔG even higher. This line never reaches the zero line.'
  },
  {
    key: 'ΔH>0, ΔS>0', dH: 40, dS: 0.058, color: '#e2b02e',
    l1: 'ΔH > 0', l2: 'ΔS > 0', labelT: 300,
    title: 'ΔH > 0, ΔS > 0 — spontaneous only when hot',
    desc: 'The positive ΔH starts this reaction in the nonspontaneous pink half, but the positive ΔS gives a downward slope of −ΔS. Above the crossover temperature T = ΔH/ΔS the entropy term outweighs the enthalpy term and ΔG becomes negative.'
  },
  {
    key: 'ΔH<0, ΔS<0', dH: -40, dS: -0.061, color: '#e2b02e',
    l1: 'ΔH < 0', l2: 'ΔS < 0', labelT: 300,
    title: 'ΔH < 0, ΔS < 0 — spontaneous only when cold',
    desc: 'The negative ΔH starts this reaction in the spontaneous green half, but the negative ΔS makes the slope −ΔS positive, so heating raises ΔG. Above T = ΔH/ΔS the unfavourable entropy change wins and the reaction becomes nonspontaneous.'
  },
  {
    key: 'ΔH<0, ΔS>0', dH: -40, dS: 0.05, color: '#86b53f',
    l1: 'ΔH < 0', l2: 'ΔS > 0', labelT: 350,
    title: 'ΔH < 0, ΔS > 0 — always spontaneous',
    desc: 'Both terms favour the reaction: negative ΔH puts the line in the green half and positive ΔS tilts it further down as temperature rises. ΔG stays negative at every temperature.'
  }
];

var figState = { T: 0, sel: 'All four', step: 0 };

function figG(c, T) { return c.dH - T * c.dS; }
function figCross(c) {
  if (c.dS === 0) return null;
