    ctx.textBaseline = 'top';
    for (var i = 0; i < CASES.length; i++) {
      var c = CASES[i];
      if (figDim(c)) continue;
      var pA = { x: xS.getPixelForValue(0), y: yS.getPixelForValue(figG(c, 0)) };
      var pB = { x: xS.getPixelForValue(1000), y: yS.getPixelForValue(figG(c, 1000)) };
      var ang = Math.atan2(pB.y - pA.y, pB.x - pA.x);
