      ctx.restore();
    }
    ctx.restore();

    // ---- region labels ----
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    var fontR = fsRegion.toFixed(1) + 'px sans-serif';
    haloText(ctx, 'Nonspontaneous', ca.left + w * 0.72, ca.top + h * 0.22, fontR, '#1b1b1b', fsRegion * 0.3);
    haloText(ctx, 'Spontaneous', ca.left + w * 0.72, ca.top + h * 0.77, fontR, '#1b1b1b', fsRegion * 0.3);
    ctx.restore();

    // ---- rotated ΔG annotations near the left edge ----
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    var fontV = 'italic ' + fs.toFixed(1) + 'px sans-serif';
    var vx = ca.left + Math.max(10, w * 0.045);
    ctx.translate(vx, yS.getPixelForValue(72));
    ctx.rotate(-Math.PI / 2);
    haloText(ctx, 'ΔG > 0', 0, 0, fontV, '#222', fs * 0.32);
    ctx.restore();
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.translate(vx, yS.getPixelForValue(-72));
    ctx.rotate(-Math.PI / 2);
    haloText(ctx, 'ΔG < 0', 0, 0, fontV, '#222', fs * 0.32);
    ctx.restore();

    // ---- single-case annotations ----
    if (figState.sel !== 'All four') {
      var sc = null;
      for (var k = 0; k < CASES.length; k++) if (CASES[k].key === figState.sel) sc = CASES[k];
      if (sc) {
        var ix = xS.getPixelForValue(0), iy = yS.getPixelForValue(sc.dH);
        var r = Math.max(3, Math.min(6, s * 0.011));
        ctx.save();
        ctx.beginPath();
        ctx.arc(ix, iy, r, 0, Math.PI * 2);
        ctx.fillStyle = sc.color;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.fill();
        ctx.stroke();
        ctx.textAlign = 'left';
        ctx.textBaseline = 'bottom';
        haloText(ctx, 'intercept = ΔH', ix + r + 5, iy - r - 2,
          fs.toFixed(1) + 'px sans-serif', '#333', fs * 0.34);

        // slope annotation part-way along the line
        var st = 800;
        var sx = xS.getPixelForValue(st), sy = yS.getPixelForValue(figG(sc, st));
        var above = (sy - fs * 2.4 > ca.top + 6);
        ctx.textAlign = 'center';
        ctx.textBaseline = above ? 'bottom' : 'top';
        var ty = above ? sy - fs * 0.9 : sy + fs * 0.9;
        haloText(ctx, 'slope = −ΔS', sx, ty, fs.toFixed(1) + 'px sans-serif', '#333', fs * 0.34);
        ctx.restore();
      }
    }

    // ---- temperature cursor + markers ----
    if (figState.T > 0) {
      var cx = xS.getPixelForValue(figState.T);
      ctx.save();
      ctx.strokeStyle = '#4a4a4a';
      ctx.lineWidth = Math.max(1, s * 0.0035);
      ctx.setLineDash([5, 4]);
      ctx.beginPath();
      ctx.moveTo(cx, ca.top);
      ctx.lineTo(cx, ca.bottom);
      ctx.stroke();
      ctx.setLineDash([]);
      var mr = Math.max(3.5, Math.min(9, s * 0.017));
      for (var m = 0; m < CASES.length; m++) {
        var cc = CASES[m];
        if (figDim(cc)) continue;
        var g = figG(cc, figState.T);
        var my = yS.getPixelForValue(g);
        if (my < ca.top - 2 || my > ca.bottom + 2) continue;
        ctx.beginPath();
        ctx.arc(cx, my, mr, 0, Math.PI * 2);
        ctx.fillStyle = (g > 0) ? '#b03a2e' : '#3d7a24';
        ctx.fill();
        ctx.lineWidth = Math.max(1.5, mr * 0.42);
        ctx.strokeStyle = '#ffffff';
        ctx.stroke();
        ctx.lineWidth = Math.max(1, mr * 0.28);
