      ctx.textAlign = (cx > ca.left + w * 0.85) ? 'right' : 'left';
      ctx.textBaseline = 'bottom';
      haloText(ctx, figState.T + ' K', cx + (ctx.textAlign === 'right' ? -5 : 5), ca.bottom - 3,
