  { title: 'Never spontaneous: ΔH > 0, ΔS < 0', narration: 'The red line starts in the pink half (positive ΔH) and climbs as temperature rises, because −TΔS is positive. It never reaches zero — heating only makes things worse.', state: { caseSelect: 'ΔH>0, ΔS<0', temperature: 700 } },
  { title: 'Always spontaneous: ΔH < 0, ΔS > 0', narration: 'The green line starts in the green half (negative ΔH) and falls further as temperature rises. Both terms favor the reaction, so it is spontaneous at every temperature.', state: { caseSelect: 'ΔH<0, ΔS>0', temperature: 700 } },
