// @FIGURE_CODE_BEGIN
var FIG_PINK = '#f4d7d4', FIG_GREEN = '#e3ecd5';

var CASES = [
  {
    key: 'ΔH>0, ΔS<0', dH: 40, dS: -0.055, color: '#c0392b',
    l1: 'ΔH > 0', l2: 'ΔS < 0', labelT: 300,
    title: 'ΔH > 0, ΔS < 0 — never spontaneous',
    desc: 'Both terms work against the reaction: the positive ΔH puts the line in the pink half at low T, and because ΔS is negative the term −TΔS is positive, so heating pushes ΔG even higher. This line never reaches the zero line.'
  },
  {
    key: 'ΔH>0, ΔS>0', dH: 40, dS: 0.058, color: '#e2b02e',
    l1: 'ΔH > 0', l2: 'ΔS > 0', labelT: 300,
    title: 'ΔH > 0, ΔS > 0 — spontaneous only when hot',
    desc: 'The positive ΔH starts this reaction in the nonspontaneous pink half, but the positive ΔS gives a downward slope of −ΔS. Above the crossover temperature T = ΔH/ΔS the entropy term outweighs the enthalpy term and ΔG becomes negative.'
  },
  {
    key: 'ΔH<0, ΔS<0', dH: -40, dS: -0.061, color: '#e2b02e',
    l1: 'ΔH < 0', l2: 'ΔS < 0', labelT: 300,
    title: 'ΔH < 0, ΔS < 0 — spontaneous only when cold',
    desc: 'The negative ΔH starts this reaction in the spontaneous green half, but the negative ΔS makes the slope −ΔS positive, so heating raises ΔG. Above T = ΔH/ΔS the unfavourable entropy change wins and the reaction becomes nonspontaneous.'
  },
  {
    key: 'ΔH<0, ΔS>0', dH: -40, dS: 0.05, color: '#86b53f',
    l1: 'ΔH < 0', l2: 'ΔS > 0', labelT: 350,
    title: 'ΔH < 0, ΔS > 0 — always spontaneous',
    desc: 'Both terms favour the reaction: negative ΔH puts the line in the green half and positive ΔS tilts it further down as temperature rises. ΔG stays negative at every temperature.'
  }
];

var figState = { T: 0, sel: 'All four', step: 0 };

function figG(c, T) { return c.dH - T * c.dS; }
function figCross(c) {
  if (c.dS === 0) return null;
  var t = c.dH / c.dS;
  return (t > 5 && t < 995) ? t : null;
}
function figDim(c) { return figState.sel !== 'All four' && figState.sel !== c.key; }

var figContainer = document.getElementById('container');
var figCanvas = document.createElement('canvas');
figCanvas.style.cssText = 'width:100%;height:100%;display:block';
figContainer.appendChild(figCanvas);

function haloText(ctx, text, x, y, font, color, lw) {
  ctx.font = font;
  ctx.lineJoin = 'round';
  ctx.lineWidth = lw || 3.5;
  ctx.strokeStyle = 'rgba(255,255,255,0.92)';
  ctx.strokeText(text, x, y);
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
}

var bgPlugin = {
  id: 'figBg',
  beforeDatasetsDraw: function (chart) {
    var ctx = chart.ctx, ca = chart.chartArea;
    if (!ca) return;
    var y0 = chart.scales.y.getPixelForValue(0);
    ctx.save();
    ctx.fillStyle = FIG_PINK;
    ctx.fillRect(ca.left, ca.top, ca.right - ca.left, y0 - ca.top);
    ctx.fillStyle = FIG_GREEN;
    ctx.fillRect(ca.left, y0, ca.right - ca.left, ca.bottom - y0);
    ctx.strokeStyle = '#8d8d8d';
    ctx.lineWidth = Math.max(1, Math.min(2.2, (ca.bottom - ca.top) * 0.004));
    ctx.setLineDash([8, 6]);
    ctx.beginPath();
    ctx.moveTo(ca.left, y0);
    ctx.lineTo(ca.right, y0);
    ctx.stroke();
    ctx.restore();
  }
};

var annPlugin = {
  id: 'figAnn',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, ca = chart.chartArea;
    if (!ca) return;
    var w = ca.right - ca.left, h = ca.bottom - ca.top;
    var s = Math.min(w, h);
    var fs = Math.max(8, Math.min(15, s * 0.033));
    var fsRegion = Math.max(10, Math.min(21, s * 0.048));
    var xS = chart.scales.x, yS = chart.scales.y;
    var y0 = yS.getPixelForValue(0);

    // ---- inline rotated labels on each line ----
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    for (var i = 0; i < CASES.length; i++) {
      var c = CASES[i];
      if (figDim(c)) continue;
      var pA = { x: xS.getPixelForValue(0), y: yS.getPixelForValue(figG(c, 0)) };
      var pB = { x: xS.getPixelForValue(1000), y: yS.getPixelForValue(figG(c, 1000)) };
      var ang = Math.atan2(pB.y - pA.y, pB.x - pA.x);
      var px = xS.getPixelForValue(c.labelT), py = yS.getPixelForValue(figG(c, c.labelT));
      ctx.save();
      ctx.translate(px, py);
      ctx.rotate(ang);
      var font = 'italic ' + fs.toFixed(1) + 'px sans-serif';
      haloText(ctx, c.l1, 0, fs * 0.45, font, '#222', fs * 0.32);
      haloText(ctx, c.l2, 0, fs * 0.45 + fs * 1.25, font, '#222', fs * 0.32);
      ctx.restore();
    }
    ctx.restore();

    // ---- region labels ----
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    var fontR = fsRegion.toFixed(1) + 'px sans-serif';
    haloText(ctx, 'Nonspontaneous', ca.left + w * 0.72, ca.top + h * 0.22, fontR, '#1b1b1b', fsRegion * 0.3);
    haloText(ctx, 'Spontaneous', ca.left + w * 0.72, ca.top + h * 0.77, fontR, '#1b1b1b', fsRegion * 0.3);
    ctx.restore();

    // ---- rotated ΔG annotations near the left edge ----
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    var fontV = 'italic ' + fs.toFixed(1) + 'px sans-serif';
    var vx = ca.left + Math.max(10, w * 0.045);
    ctx.translate(vx, yS.getPixelForValue(72));
    ctx.rotate(-Math.PI / 2);
    haloText(ctx, 'ΔG > 0', 0, 0, fontV, '#222', fs * 0.32);
    ctx.restore();
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.translate(vx, yS.getPixelForValue(-72));
    ctx.rotate(-Math.PI / 2);
    haloText(ctx, 'ΔG < 0', 0, 0, fontV, '#222', fs * 0.32);
    ctx.restore();

    // ---- single-case annotations ----
    if (figState.sel !== 'All four') {
      var sc = null;
      for (var k = 0; k < CASES.length; k++) if (CASES[k].key === figState.sel) sc = CASES[k];
      if (sc) {
        var ix = xS.getPixelForValue(0), iy = yS.getPixelForValue(sc.dH);
        var r = Math.max(3, Math.min(6, s * 0.011));
        ctx.save();
        ctx.beginPath();
        ctx.arc(ix, iy, r, 0, Math.PI * 2);
        ctx.fillStyle = sc.color;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.fill();
        ctx.stroke();
        ctx.textAlign = 'left';
        ctx.textBaseline = 'bottom';
        haloText(ctx, 'intercept = ΔH', ix + r + 5, iy - r - 2,
          fs.toFixed(1) + 'px sans-serif', '#333', fs * 0.34);

        // slope annotation part-way along the line
        var st = 800;
        var sx = xS.getPixelForValue(st), sy = yS.getPixelForValue(figG(sc, st));
        var above = (sy - fs * 2.4 > ca.top + 6);
        ctx.textAlign = 'center';
        ctx.textBaseline = above ? 'bottom' : 'top';
        var ty = above ? sy - fs * 0.9 : sy + fs * 0.9;
        haloText(ctx, 'slope = −ΔS', sx, ty, fs.toFixed(1) + 'px sans-serif', '#333', fs * 0.34);
        ctx.restore();
      }
    }

    // ---- temperature cursor + markers ----
    if (figState.T > 0) {
      var cx = xS.getPixelForValue(figState.T);
      ctx.save();
      ctx.strokeStyle = '#4a4a4a';
      ctx.lineWidth = Math.max(1, s * 0.0035);
      ctx.setLineDash([5, 4]);
      ctx.beginPath();
      ctx.moveTo(cx, ca.top);
      ctx.lineTo(cx, ca.bottom);
      ctx.stroke();
      ctx.setLineDash([]);
      var mr = Math.max(3.5, Math.min(9, s * 0.017));
      for (var m = 0; m < CASES.length; m++) {
        var cc = CASES[m];
        if (figDim(cc)) continue;
        var g = figG(cc, figState.T);
        var my = yS.getPixelForValue(g);
        if (my < ca.top - 2 || my > ca.bottom + 2) continue;
        ctx.beginPath();
        ctx.arc(cx, my, mr, 0, Math.PI * 2);
        ctx.fillStyle = (g > 0) ? '#b03a2e' : '#3d7a24';
        ctx.fill();
        ctx.lineWidth = Math.max(1.5, mr * 0.42);
        ctx.strokeStyle = '#ffffff';
        ctx.stroke();
        ctx.lineWidth = Math.max(1, mr * 0.28);
        ctx.strokeStyle = cc.color;
        ctx.beginPath();
        ctx.arc(cx, my, mr + Math.max(1.4, mr * 0.34), 0, Math.PI * 2);
        ctx.stroke();
      }
      // small T tag at the very bottom of the cursor
      ctx.textAlign = (cx > ca.left + w * 0.85) ? 'right' : 'left';
      ctx.textBaseline = 'bottom';
      haloText(ctx, figState.T + ' K', cx + (ctx.textAlign === 'right' ? -5 : 5), ca.bottom - 3,
        fs.toFixed(1) + 'px sans-serif', '#333', fs * 0.34);
      ctx.restore();
    }
  }
};

var figDatasets = CASES.map(function (c) {
  return {
    label: c.key,
    data: [{ x: 0, y: figG(c, 0) }, { x: 1000, y: figG(c, 1000) }],
    borderColor: c.color,
    borderWidth: 4,
    pointRadius: 0,
    tension: 0,
    fill: false
  };
});

var figChart = new Chart(figCanvas.getContext('2d'), {
  type: 'line',
  data: { datasets: figDatasets },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    parsing: false,
    events: [],
    layout: { padding: { top: 6, right: 6 } },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: {
        type: 'linear', min: 0, max: 1000,
        grid: { display: false, drawTicks: false },
        border: { display: true, color: '#000', width: 2 },
        ticks: { display: false },
        title: {
          display: true, text: 'Increasing temperature (K)',
          color: '#000', font: { size: 13, weight: 'bold' }
        }
      },
      y: {
        type: 'linear', min: -100, max: 100,
        grid: { display: false, drawTicks: true, tickLength: 5 },
        border: { display: true, color: '#000', width: 2 },
        afterBuildTicks: function (axis) { axis.ticks = [{ value: 0 }]; },
        ticks: { color: '#000', font: { size: 13 }, callback: function () { return '0'; } },
        title: {
          display: true, text: 'Free energy',
          color: '#000', font: { size: 13, weight: 'bold' }
        }
      }
    }
  },
  plugins: [bgPlugin, annPlugin]
});
window.__markRendered();

/* ---------------- readout ---------------- */
function updateReadout() {
  var el = document.getElementById('readout');
  var html = '';
  for (var i = 0; i < CASES.length; i++) {
    var c = CASES[i];
    var g = figG(c, figState.T);
    var sp = g < 0;
    var dim = figDim(c);
    var cross = figCross(c);
    html += '<span style="display:flex;align-items:center;gap:5px;opacity:' + (dim ? 0.35 : 1) + '">' +
      '<span style="flex:0 0 16px;height:0;border-top:3px solid ' + c.color + ';"></span>' +
      '<span style="flex:0 0 84px;">' + c.l1 + ', ' + c.l2 + '</span>' +
      '<span style="flex:0 0 46px;text-align:right;">ΔG ' + (g >= 0 ? '&gt;' : '&lt;') + ' 0</span>' +
      '<span style="flex:1;text-align:right;font-weight:600;color:' + (sp ? '#3d7a24' : '#b03a2e') + '">' +
      (sp ? 'spontaneous' : 'nonspont.') + '</span></span>' +
      (cross ? '<span style="display:block;margin:-1px 0 3px 21px;font-size:10px;color:#666;opacity:' +
        (dim ? 0.35 : 1) + '">flips at T ≈ ' + Math.round(cross) + ' K</span>' : '');
  }
  html += '<span style="display:block;margin-top:3px;color:#555">Cursor: T = ' + figState.T + ' K</span>';
  el.innerHTML = html;
}

/* ---------------- interactions ---------------- */
function update_temperature(v) {
  figState.T = v;
  updateReadout();
  figChart.update('none');
}

function toggle_caseSelect(val) {
  figState.sel = val;
  for (var i = 0; i < CASES.length; i++) {
    var dim = figDim(CASES[i]);
    figChart.data.datasets[i].borderColor = dim ? '#d6d6d6' : CASES[i].color;
    figChart.data.datasets[i].borderWidth = dim ? 2.5 : 4;
  }
  updateReadout();
  figChart.update('none');
}

/* ---------------- demo steps ---------------- */
var DEMO = [
  { title: 'The map: two halves, one dashed line', narration: 'Above the gray dashed line ΔG is positive and the process is nonspontaneous; below it ΔG is negative and the process is spontaneous. Every line here is just ΔG = ΔH − TΔS plotted against T.', state: { caseSelect: 'All four', temperature: 0 } },
  { title: 'Never spontaneous: ΔH > 0, ΔS < 0', narration: 'The red line starts in the pink half (positive ΔH) and climbs as temperature rises, because −TΔS is positive. It never reaches zero — heating only makes things worse.', state: { caseSelect: 'ΔH>0, ΔS<0', temperature: 700 } },
  { title: 'Always spontaneous: ΔH < 0, ΔS > 0', narration: 'The green line starts in the green half (negative ΔH) and falls further as temperature rises. Both terms favor the reaction, so it is spontaneous at every temperature.', state: { caseSelect: 'ΔH<0, ΔS>0', temperature: 700 } },
  { title: 'Turns on when heated: ΔH > 0, ΔS > 0', narration: 'This yellow line begins nonspontaneous but slopes downward. Push the temperature cursor past its x-intercept and the marker drops into the green half — the entropy term has overtaken the enthalpy term.', state: { caseSelect: 'ΔH>0, ΔS>0', temperature: 620 } },
  { title: 'Turns off when heated: ΔH < 0, ΔS < 0', narration: 'The other yellow line starts spontaneous but slopes upward, crossing zero at its own temperature. Above that point the unfavorable entropy change wins and the reaction stops being spontaneous.', state: { caseSelect: 'ΔH<0, ΔS<0', temperature: 620 } },
  { title: 'Sweep all four at once', narration: 'With all four lines showing, slide the temperature cursor from cold to hot: the red and green markers stay on their own sides, while only the two yellow markers cross the dashed line — each at a different crossover temperature.', state: { caseSelect: 'All four', temperature: 900 } }
];

function applyStep(i) {
  figState.step = Math.max(0, Math.min(DEMO.length - 1, i));
  var st = DEMO[figState.step];
  var sel = document.getElementById('caseSelectInput');
  sel.value = st.state.caseSelect;
  toggle_caseSelect(st.state.caseSelect);
  var sl = document.getElementById('temperatureInput');
  sl.value = st.state.temperature;
  document.getElementById('temperatureVal').value = st.state.temperature;
  update_temperature(+st.state.temperature);
  document.getElementById('demoNarration').innerHTML =
    '<b>' + st.title + '</b><br>' + st.narration;
  document.getElementById('stepLabel').textContent =
    'Step ' + (figState.step + 1) + ' / ' + DEMO.length;
}
function nextStep() { applyStep(figState.step + 1); }
function prevStep() { applyStep(figState.step - 1); }

/* ---------------- hover / click on lines ---------------- */
function figHitTest(evt) {
  var rect = figCanvas.getBoundingClientRect();
  var px = (evt.clientX - rect.left) * (figCanvas.width / rect.width) / (window.devicePixelRatio || 1);
  var py = (evt.clientY - rect.top) * (figCanvas.height / rect.height) / (window.devicePixelRatio || 1);
  var ca = figChart.chartArea;
  if (!ca || px < ca.left || px > ca.right || py < ca.top || py > ca.bottom) return null;
  var T = figChart.scales.x.getValueForPixel(px);
  var best = null, bd = 1e9;
  for (var i = 0; i < CASES.length; i++) {
    var c = CASES[i];
    if (figDim(c)) continue;
    var ly = figChart.scales.y.getPixelForValue(figG(c, T));
    var d = Math.abs(ly - py);
    if (d < bd) { bd = d; best = c; }
  }
  return (bd < Math.max(8, figChart.chartArea.height * 0.018)) ? { c: best, T: T } : null;
}

figCanvas.addEventListener('mousemove', function (e) {
  var hit = figHitTest(e);
  if (hit) {
    var g = figG(hit.c, hit.T);
    showTooltip(hit.c.l1 + ', ' + hit.c.l2 + '  →  ΔG ' + (g >= 0 ? '> 0 (nonspontaneous)' : '< 0 (spontaneous)') +
      ' at T ≈ ' + Math.round(hit.T) + ' K', e);
    figCanvas.style.cursor = 'pointer';
  } else {
    hideTooltip();
    figCanvas.style.cursor = 'default';
  }
});
figCanvas.addEventListener('mouseleave', function () { hideTooltip(); });
figCanvas.addEventListener('click', function (e) {
  var hit = figHitTest(e);
  if (hit) showPopup(hit.c.title, hit.c.desc);
});

applyStep(0);
// @FIGURE_CODE_END

