    }
  ],
  "demo_steps": [
    {
      "title": "The map: two halves, one dashed line",
      "narration": "Above the gray dashed line ΔG is positive and the process is nonspontaneous; below it ΔG is negative and the process is spontaneous. Every line here is just ΔG = ΔH − TΔS plotted against T.",
      "state": {
        "caseSelect": "All four",
