Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="display:block;font-weight:700;font-size:12px;">ΔG = ΔH − TΔS</span>
<span id="demoNarration" style="display:block;margin:0;font-size:11px;line-height:1.4;color:#333;min-height:74px"></span>
<span style="display:flex;gap:6px;align-items:center;">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px;min-width:70px;text-align:center">Step 1 / 6</span>
  <button onclick="nextStep()">▶</button>
</span>
<label>Temperature (K): <output id="temperatureVal">0</output>
  <input id="temperatureInput" type="range" min="0" max="1000" step="10" value="0"
         oninput="document.getElementById('temperatureVal').value=this.value;update_temperature(+this.value)">
</label>
<label>Sign combination:
  <select id="caseSelectInput" onchange="toggle_caseSelect(this.value)" style="font-size:11px;padding:2px">
    <option value="All four">All four</option>
    <option value="ΔH&gt;0, ΔS&lt;0">ΔH&gt;0, ΔS&lt;0 (never)</option>
    <option value="ΔH&gt;0, ΔS&gt;0">ΔH&gt;0, ΔS&gt;0 (turns on)</option>
    <option value="ΔH&lt;0, ΔS&lt;0">ΔH&lt;0, ΔS&lt;0 (turns off)</option>
    <option value="ΔH&lt;0, ΔS&gt;0">ΔH&lt;0, ΔS&gt;0 (always)</option>
  </select>
</label>
<span id="readout" style="display:block;font-size:11px;line-height:1.5;"></span>
<span style="display:block;font-size:10px;color:#666;line-height:1.35;">Hover a line for its meaning; click it for a fuller explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var FIG_PINK = '#f4d7d4', FIG_GREEN = '#e3ecd5';
var FIG_ASPECT = 0.78;            // width : height (portrait, like the source)
var figGutter = 26;               // empty gutter inside the y-axis for ΔG labels
var figTagSpace = 22;             // empty strip under the x-axis for the T tag
var SERIF = '"Times New Roman", Times, Georgia, serif';

var CASES = [
  {
    key: 'ΔH>0, ΔS<0', dH: 40, dS: -0.055, color: '#c0392b',
    l1: 'ΔH > 0', l2: 'ΔS < 0', labelT: 250,
    title: 'ΔH > 0, ΔS < 0 — never spontaneous',
    desc: 'Both terms work against the reaction: the positive ΔH puts the line in the pink half at low T, and because ΔS is negative the term −TΔS is positive, so heating pushes ΔG even higher. This line never reaches the zero line.'
  },
  {
    key: 'ΔH>0, ΔS>0', dH: 40, dS: 0.058, color: '#e2b02e',
    l1: 'ΔH > 0', l2: 'ΔS > 0', labelT: 335,
    title: 'ΔH > 0, ΔS > 0 — spontaneous only when hot',
    desc: 'The positive ΔH starts this reaction in the nonspontaneous pink half, but the positive ΔS gives a downward slope of −ΔS. Above the crossover temperature T = ΔH/ΔS the entropy term outweighs the enthalpy term and ΔG becomes negative.'
  },
  {
    key: 'ΔH<0, ΔS<0', dH: -40, dS: -0.061, color: '#e2b02e',
    l1: 'ΔH < 0', l2: 'ΔS < 0', labelT: 290,
    title: 'ΔH < 0, ΔS < 0 — spontaneous only when cold',
    desc: 'The negative ΔH starts this reaction in the spontaneous green half, but the negative ΔS makes the slope −ΔS positive, so heating raises ΔG. Above T = ΔH/ΔS the unfavourable entropy change wins and the reaction becomes nonspontaneous.'
  },
  {
    key: 'ΔH<0, ΔS>0', dH: -40, dS: 0.05, color: '#86b53f',
    l1: 'ΔH < 0', l2: 'ΔS > 0', labelT: 390,
    title: 'ΔH < 0, ΔS > 0 — always spontaneous',
    desc: 'Both terms favour the reaction: negative ΔH puts the line in the green half and positive ΔS tilts it further down as temperature rises. ΔG stays negative at every temperature.'
  }
];

var figState = { T: 0, sel: 'All four', step: 0 };

function figG(c, T) { return c.dH - T * c.dS; }
function figCross(c) {
  if (c.dS === 0) return null;
  var t = c.dH / c.dS;
  return (t > 5 && t < 995) ? t : null;
}
function figDim(c) { return figState.sel !== 'All four' && figState.sel !== c.key; }

/* inline ΔH/ΔS label position: staggered along each line, exactly as in the
   source, and FIXED (never jumps while the cursor is dragged) */
function inlineLabelT(c) {
  return (figState.sel === 'All four') ? c.labelT : 520;
}

/* ---------------- mount: portrait-constrained canvas ---------------- */
var figContainer = document.getElementById('container');
var figOuter = document.createElement('div');
figOuter.style.cssText = 'position:absolute;inset:0;display:flex;align-items:center;justify-content:center;';
var figInner = document.createElement('div');
figInner.style.cssText = 'position:relative;';
var figCanvas = document.createElement('canvas');
figCanvas.style.cssText = 'width:100%;height:100%;display:block';
figInner.appendChild(figCanvas);
figOuter.appendChild(figInner);
figContainer.appendChild(figOuter);

function figLayout(w, h) {
  if (!w || !h) return;
  var tw = Math.min(w, h * FIG_ASPECT);
  var th = Math.min(h, tw / FIG_ASPECT);
  figInner.style.width = Math.round(tw) + 'px';
  figInner.style.height = Math.round(th) + 'px';
  figGutter = Math.max(16, Math.min(34, tw * 0.058));
  figTagSpace = Math.max(16, Math.min(30, tw * 0.05));
  if (window.figChart) { figChart.resize(); figChart.update('none'); }
}
document.addEventListener('fig-resize', function (e) {
  figLayout(e.detail.width, e.detail.height);
});
(function () {
  var st = getComputedStyle(figContainer);
  var padX = (parseFloat(st.paddingLeft) || 0) + (parseFloat(st.paddingRight) || 0);
  var padY = (parseFloat(st.paddingTop) || 0) + (parseFloat(st.paddingBottom) || 0);
  figLayout(figContainer.clientWidth - padX, figContainer.clientHeight - padY);
})();

function haloText(ctx, text, x, y, font, color, lw) {
  ctx.font = font;
  ctx.lineJoin = 'round';
  ctx.lineWidth = Math.max(1.4, lw || 3);
  ctx.strokeStyle = 'rgba(255,255,255,0.92)';
  ctx.strokeText(text, x, y);
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
}

var bgPlugin = {
  id: 'figBg',
  beforeDatasetsDraw: function (chart) {
    var ctx = chart.ctx, ca = chart.chartArea;
    if (!ca) return;
    var y0 = chart.scales.y.getPixelForValue(0);
    ctx.save();
    ctx.fillStyle = FIG_PINK;
    ctx.fillRect(ca.left, ca.top, ca.right - ca.left, y0 - ca.top);
    ctx.fillStyle = FIG_GREEN;
    ctx.fillRect(ca.left, y0, ca.right - ca.left, ca.bottom - y0);
    ctx.strokeStyle = '#8d8d8d';
    ctx.lineWidth = Math.max(1, Math.min(2.2, (ca.bottom - ca.top) * 0.004));
    ctx.setLineDash([8, 6]);
    ctx.beginPath();
    ctx.moveTo(ca.left, y0);
    ctx.lineTo(ca.right, y0);
    ctx.stroke();
    ctx.restore();
  }
};

var annPlugin = {
  id: 'figAnn',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, ca = chart.chartArea;
    if (!ca) return;
    var w = ca.right - ca.left, h = ca.bottom - ca.top;
    var s = Math.min(w, h);
    var fs = Math.max(12, Math.min(23, w * 0.047));       // inline ΔH/ΔS labels (serif italic)
    var fsG = Math.max(10, Math.min(18, w * 0.040));      // ΔG gutter labels
    var fsR = Math.max(12, Math.min(24, w * 0.048));      // region labels
    var fsA = Math.max(9, Math.min(14, w * 0.032));       // small annotations
    var xS = chart.scales.x, yS = chart.scales.y;
    var fontInline = 'italic ' + fs.toFixed(1) + 'px ' + SERIF;

    /* ---- pre-compute inline label geometry (used for collision dimming) ---- */
    var labelInfo = [];
    for (var i = 0; i < CASES.length; i++) {
      var c = CASES[i];
      if (figDim(c)) continue;
      var pA = { x: xS.getPixelForValue(0), y: yS.getPixelForValue(figG(c, 0)) };
      var pB = { x: xS.getPixelForValue(1000), y: yS.getPixelForValue(figG(c, 1000)) };
      var lt = inlineLabelT(c);
      labelInfo.push({
        c: c,
        x: xS.getPixelForValue(lt),
        y: yS.getPixelForValue(figG(c, lt)),
        ang: Math.atan2(pB.y - pA.y, pB.x - pA.x)
      });
    }
    ctx.save();
    ctx.font = fontInline;
    var halfW = fs * 2.4;
    for (var q = 0; q < labelInfo.length; q++) {
      var wl = Math.max(ctx.measureText(labelInfo[q].c.l1).width,
        ctx.measureText(labelInfo[q].c.l2).width);
      labelInfo[q].hw = wl / 2 + fs * 0.4;
    }
    ctx.restore();

    function nearLabel(mx, my) {
      for (var k = 0; k < labelInfo.length; k++) {
        var L = labelInfo[k];
        var dx = mx - L.x, dy = my - L.y;
        var cs = Math.cos(L.ang), sn = Math.sin(L.ang);
        var u = dx * cs + dy * sn;
        var v = -dx * sn + dy * cs;
        if (Math.abs(u) < (L.hw || halfW) + fs * 0.4 && v > -fs * 1.0 && v < fs * 3.3) return true;
      }
      return false;
    }

    /* ---- region labels ---- */
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    var fontR = fsR.toFixed(1) + 'px Helvetica, Arial, sans-serif';
    haloText(ctx, 'Nonspontaneous', ca.left + w * 0.72, ca.top + h * 0.25, fontR, '#1b1b1b', fsR * 0.26);
    haloText(ctx, 'Spontaneous', ca.left + w * 0.72, ca.top + h * 0.755, fontR, '#1b1b1b', fsR * 0.26);
    ctx.restore();

    /* ---- ΔG > 0 / ΔG < 0 : in the y-axis gutter, OUTSIDE the plot ---- */
    var gx = ca.left - figGutter * 0.72;
    var fontV = 'italic ' + fsG.toFixed(1) + 'px ' + SERIF;
    [[52, 'ΔG > 0'], [-52, 'ΔG < 0']].forEach(function (p) {
      ctx.save();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.translate(gx, yS.getPixelForValue(p[0]));
      ctx.rotate(-Math.PI / 2);
      ctx.font = fontV;
      ctx.fillStyle = '#1b1b1b';
      ctx.fillText(p[1], 0, 0);
      ctx.restore();
    });

    /* ---- temperature cursor + markers ---- */
    if (figState.T > 0) {
      var cx = xS.getPixelForValue(figState.T);
      ctx.save();
      ctx.globalAlpha = 0.6;
      ctx.strokeStyle = '#4a4a4a';
      ctx.lineWidth = Math.max(1, s * 0.0035);
      ctx.setLineDash([5, 4]);
      ctx.beginPath();
      ctx.moveTo(cx, ca.top);
      ctx.lineTo(cx, ca.bottom + figTagSpace * 0.25);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.globalAlpha = 1;
      var mr = Math.max(3.5, Math.min(9, s * 0.019));
      for (var m = 0; m < CASES.length; m++) {
        var cc = CASES[m];
        if (figDim(cc)) continue;
        var g = figG(cc, figState.T);
        var my = yS.getPixelForValue(g);
        if (my < ca.top - 2 || my > ca.bottom + 2) continue;
        var masked = nearLabel(cx, my);      // marker sits on an inline label
        ctx.save();
        ctx.globalAlpha = masked ? 0.42 : 1;
        ctx.beginPath();
        ctx.arc(cx, my, mr, 0, Math.PI * 2);
        ctx.fillStyle = (g > 0) ? '#b03a2e' : '#3d7a24';
        ctx.fill();
        if (!masked) {
          ctx.lineWidth = Math.max(1.5, mr * 0.42);
          ctx.strokeStyle = '#ffffff';
          ctx.stroke();
          ctx.lineWidth = Math.max(1, mr * 0.28);
          ctx.strokeStyle = cc.color;
          ctx.beginPath();
          ctx.arc(cx, my, mr + Math.max(1.4, mr * 0.34), 0, Math.PI * 2);
          ctx.stroke();
        }
        ctx.restore();
      }
      /* T tag lives in the reserved strip BELOW the x-axis line */
      var tTxt = figState.T + ' K';
      ctx.font = '600 ' + fsA.toFixed(1) + 'px Helvetica, Arial, sans-serif';
      var tw = ctx.measureText(tTxt).width + fsA * 0.9;
      var th = fsA * 1.5;
      var tx = Math.max(ca.left + tw / 2, Math.min(ca.right - tw / 2, cx));
      var ty = ca.bottom + figTagSpace * 0.28;
      ctx.beginPath();
      var rr = th * 0.3;
      ctx.moveTo(tx - tw / 2 + rr, ty);
      ctx.arcTo(tx + tw / 2, ty, tx + tw / 2, ty + th, rr);
      ctx.arcTo(tx + tw / 2, ty + th, tx - tw / 2, ty + th, rr);
      ctx.arcTo(tx - tw / 2, ty + th, tx - tw / 2, ty, rr);
      ctx.arcTo(tx - tw / 2, ty, tx + tw / 2, ty, rr);
      ctx.closePath();
      ctx.fillStyle = '#ffffff';
      ctx.fill();
      ctx.lineWidth = 1;
      ctx.strokeStyle = '#9a9a9a';
      ctx.stroke();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = '#333';
      ctx.fillText(tTxt, tx, ty + th / 2 + 0.5);
      ctx.restore();
    }

    /* ---- single-case annotations (clamped inside the frame) ---- */
    if (figState.sel !== 'All four' && w > 190) {
      var sc = null;
      for (var k2 = 0; k2 < CASES.length; k2++) if (CASES[k2].key === figState.sel) sc = CASES[k2];
      if (sc) {
        ctx.save();
        ctx.font = fsA.toFixed(1) + 'px Helvetica, Arial, sans-serif';
        var ix = xS.getPixelForValue(0), iy = yS.getPixelForValue(sc.dH);
        var r = Math.max(3, Math.min(6.5, s * 0.013));
        var rising = sc.dS < 0;                       // slope = −ΔS
        var off = fsA * 2.1;
        var ly = rising ? iy + off : iy - off;
        if (ly < ca.top + fsA * 1.2) ly = iy + off;
        if (ly > ca.bottom - fsA * 1.2) ly = iy - off;
        ly = Math.max(ca.top + fsA * 1.2, Math.min(ca.bottom - fsA * 1.2, ly));

        var itxt = 'intercept = ΔH';
        var itw = ctx.measureText(itxt).width;
        var itx = ix + fsA * 0.9;
        if (itx + itw > ca.right - 5) itx = Math.max(ca.left + 3, ca.right - 5 - itw);

        ctx.strokeStyle = '#8a8a8a';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(ix, ly > iy ? iy + r : iy - r);
        ctx.lineTo(itx - fsA * 0.35, ly);
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(ix, iy, r, 0, Math.PI * 2);
        ctx.fillStyle = sc.color;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.fill();
        ctx.stroke();

        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        haloText(ctx, itxt, itx, ly, fsA.toFixed(1) + 'px Helvetica, Arial, sans-serif', '#333', fsA * 0.36);

        // slope callout near the right end of the line
        var stT = 840;
        var sx = xS.getPixelForValue(stT), sy = yS.getPixelForValue(figG(sc, stT));
        var sTxt = 'slope = −ΔS';
        ctx.font = fsA.toFixed(1) + 'px Helvetica, Arial, sans-serif';
        var stw = ctx.measureText(sTxt).width;
        var above = sc.dS > 0;                     // falling line → text above it
        var sty = above ? sy - fsA * 1.7 : sy + fsA * 1.7;
        if (sty < ca.top + fsA * 1.1) sty = sy + fsA * 1.7;
        if (sty > ca.bottom - fsA * 1.1) sty = sy - fsA * 1.7;
        sty = Math.max(ca.top + fsA * 1.1, Math.min(ca.bottom - fsA * 1.1, sty));
        var stx = Math.max(ca.left + 4, ca.right - 6 - stw);
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.strokeStyle = '#8a8a8a';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(sx, sy);
        ctx.lineTo(Math.min(sx + fsA * 0.9, stx + stw * 0.5), sty + (sty > sy ? -fsA * 0.55 : fsA * 0.55));
        ctx.stroke();
        haloText(ctx, sTxt, stx, sty, fsA.toFixed(1) + 'px Helvetica, Arial, sans-serif', '#333', fsA * 0.36);
        ctx.restore();
      }
    }

    /* ---- inline rotated ΔH/ΔS labels (serif italic, drawn last, on top) ---- */
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    for (var j = 0; j < labelInfo.length; j++) {
      var L2 = labelInfo[j];
      ctx.save();
      ctx.translate(L2.x, L2.y);
      ctx.rotate(L2.ang);
      haloText(ctx, L2.c.l1, 0, fs * 0.30, fontInline, '#141414', fs * 0.20);
      haloText(ctx, L2.c.l2, 0, fs * 0.30 + fs * 1.24, fontInline, '#141414', fs * 0.20);
      ctx.restore();
    }
    ctx.restore();
  }
};

var figDatasets = CASES.map(function (c) {
  return {
    label: c.key,
    data: [{ x: 0, y: figG(c, 0) }, { x: 1000, y: figG(c, 1000) }],
    borderColor: c.color,
    borderWidth: 4,
    pointRadius: 0,
    tension: 0,
    fill: false
  };
});

var figChart = new Chart(figCanvas.getContext('2d'), {
  type: 'line',
  data: { datasets: figDatasets },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    parsing: false,
    events: [],
    layout: { padding: { top: 8, right: 8 } },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: {
        type: 'linear', min: 0, max: 1000,
        grid: { display: false, drawTicks: false },
        border: { display: true, color: '#000', width: 2 },
        ticks: { display: false },
        afterFit: function (a) { a.height += figTagSpace; },
        title: {
          display: true, text: 'Increasing temperature (K)',
          color: '#000', font: { size: 13, weight: 'bold' }
        }
      },
      y: {
        type: 'linear', min: -100, max: 100,
        grid: { display: false, drawTicks: true, tickLength: 5 },
        border: { display: true, color: '#000', width: 2 },
        afterBuildTicks: function (axis) { axis.ticks = [{ value: 0 }]; },
        afterFit: function (a) { a.width += figGutter; },
        ticks: { color: '#000', font: { size: 13 }, callback: function () { return '0'; } },
        title: {
          display: true, text: 'Free energy',
          color: '#000', font: { size: 13, weight: 'bold' }
        }
      }
    }
  },
  plugins: [bgPlugin, annPlugin]
});
window.figChart = figChart;
window.__markRendered();

/* ---------------- readout ---------------- */
function updateReadout() {
  var el = document.getElementById('readout');
  var html = '';
  for (var i = 0; i < CASES.length; i++) {
    var c = CASES[i];
    var g = figG(c, figState.T);
    var sp = g < 0;
    var dim = figDim(c);
    var cross = figCross(c);
    html += '<span style="display:flex;align-items:center;gap:5px;opacity:' + (dim ? 0.35 : 1) + '">' +
      '<span style="flex:0 0 16px;height:0;border-top:3px solid ' + c.color + ';"></span>' +
      '<span style="flex:0 0 84px;">' + c.l1 + ', ' + c.l2 + '</span>' +
      '<span style="flex:0 0 46px;text-align:right;">ΔG ' + (g >= 0 ? '&gt;' : '&lt;') + ' 0</span>' +
      '<span style="flex:1;text-align:right;font-weight:600;color:' + (sp ? '#3d7a24' : '#b03a2e') + '">' +
      (sp ? 'spontaneous' : 'nonspont.') + '</span></span>' +
      (cross ? '<span style="display:block;margin:-1px 0 3px 21px;font-size:10px;color:#666;opacity:' +
        (dim ? 0.35 : 1) + '">flips at T ≈ ' + Math.round(cross) + ' K</span>' : '');
  }
  html += '<span style="display:block;margin-top:3px;color:#555">Cursor: T = ' + figState.T + ' K</span>';
  el.innerHTML = html;
}

/* ---------------- interactions ---------------- */
function update_temperature(v) {
  figState.T = v;
  updateReadout();
  figChart.update('none');
}

function toggle_caseSelect(val) {
  figState.sel = val;
  for (var i = 0; i < CASES.length; i++) {
    var dim = figDim(CASES[i]);
    figChart.data.datasets[i].borderColor = dim ? '#d6d6d6' : CASES[i].color;
    figChart.data.datasets[i].borderWidth = dim ? 2.5 : 4;
  }
  updateReadout();
  figChart.update('none');
}

/* ---------------- demo steps ---------------- */
var DEMO = [
  { title: 'The map: two halves, one dashed line', narration: 'Above the gray dashed line ΔG is positive and the process is nonspontaneous; below it ΔG is negative and the process is spontaneous. Every line here is just ΔG = ΔH − TΔS plotted against T.', state: { caseSelect: 'All four', temperature: 0 } },
  { title: 'Never spontaneous: ΔH > 0, ΔS < 0', narration: 'The red line starts in the pink half (positive ΔH) and climbs as temperature rises, because −TΔS is positive. It never reaches zero — heating only makes things worse.', state: { caseSelect: 'ΔH>0, ΔS<0', temperature: 700 } },
  { title: 'Always spontaneous: ΔH < 0, ΔS > 0', narration: 'The green line starts in the green half (negative ΔH) and falls further as temperature rises. Both terms favor the reaction, so it is spontaneous at every temperature.', state: { caseSelect: 'ΔH<0, ΔS>0', temperature: 700 } },
  { title: 'Turns on when heated: ΔH > 0, ΔS > 0', narration: 'This yellow line begins nonspontaneous but slopes downward. Push the temperature cursor past its x-intercept and the marker drops into the green half — the entropy term has overtaken the enthalpy term.', state: { caseSelect: 'ΔH>0, ΔS>0', temperature: 620 } },
  { title: 'Turns off when heated: ΔH < 0, ΔS < 0', narration: 'The other yellow line starts spontaneous but slopes upward, crossing zero at its own temperature. Above that point the unfavorable entropy change wins and the reaction stops being spontaneous.', state: { caseSelect: 'ΔH<0, ΔS<0', temperature: 620 } },
  { title: 'Sweep all four at once', narration: 'With all four lines showing, slide the temperature cursor from cold to hot: the red and green markers stay on their own sides, while only the two yellow markers cross the dashed line — each at a different crossover temperature.', state: { caseSelect: 'All four', temperature: 900 } }
];

function applyStep(i) {
  figState.step = Math.max(0, Math.min(DEMO.length - 1, i));
  var st = DEMO[figState.step];
  var sel = document.getElementById('caseSelectInput');
  sel.value = st.state.caseSelect;
  toggle_caseSelect(st.state.caseSelect);
  var sl = document.getElementById('temperatureInput');
  sl.value = st.state.temperature;
  document.getElementById('temperatureVal').value = st.state.temperature;
  update_temperature(+st.state.temperature);
  document.getElementById('demoNarration').innerHTML =
    '<b>' + st.title + '</b><br>' + st.narration;
  document.getElementById('stepLabel').textContent =
    'Step ' + (figState.step + 1) + ' / ' + DEMO.length;
}
function nextStep() { applyStep(figState.step + 1); }
function prevStep() { applyStep(figState.step - 1); }

/* ---------------- hover / click on lines ---------------- */
function figHitTest(evt) {
  var rect = figCanvas.getBoundingClientRect();
  var px = (evt.clientX - rect.left) * (figCanvas.width / rect.width) / (window.devicePixelRatio || 1);
  var py = (evt.clientY - rect.top) * (figCanvas.height / rect.height) / (window.devicePixelRatio || 1);
  var ca = figChart.chartArea;
  if (!ca || px < ca.left || px > ca.right || py < ca.top || py > ca.bottom) return null;
  var T = figChart.scales.x.getValueForPixel(px);
  var best = null, bd = 1e9;
  for (var i = 0; i < CASES.length; i++) {
    var c = CASES[i];
    if (figDim(c)) continue;
    var ly = figChart.scales.y.getPixelForValue(figG(c, T));
    var d = Math.abs(ly - py);
    if (d < bd) { bd = d; best = c; }
  }
  return (bd < Math.max(8, figChart.chartArea.height * 0.018)) ? { c: best, T: T } : null;
}

figCanvas.addEventListener('mousemove', function (e) {
  var hit = figHitTest(e);
  if (hit) {
    var g = figG(hit.c, hit.T);
    showTooltip(hit.c.l1 + ', ' + hit.c.l2 + '  →  ΔG ' + (g >= 0 ? '> 0 (nonspontaneous)' : '< 0 (spontaneous)') +
      ' at T ≈ ' + Math.round(hit.T) + ' K', e);
    figCanvas.style.cursor = 'pointer';
  } else {
    hideTooltip();
    figCanvas.style.cursor = 'default';
  }
});
figCanvas.addEventListener('mouseleave', function () { hideTooltip(); });
figCanvas.addEventListener('click', function (e) {
  var hit = figHitTest(e);
  if (hit) showPopup(hit.c.title, hit.c.desc);
});

applyStep(0);
